import json
d = json.load(open("/tmp/claude-0/-home-user-deepseek-harness/55912606-8da1-4dfb-bed9-3ed3a9b2403d/scratchpad/npm-audit.json"))
vulns = d["vulnerabilities"]

prod = ["bcrypt-nodejs","body-parser","consolidate","csurf","dont-sniff-mimetype","express","express-session","forever","helmet","marked","mongodb","needle","node-esapi","serve-favicon","swig","underscore"]
