def summarize(name):
    if name not in vulns:
        return None
    v = vulns[name]
    direct_advisories = [x for x in v["via"] if isinstance(x, dict)]
    sub_pkgs = [x for x in v["via"] if isinstance(x, str)]
    return {
        "severity": v.get("severity"),
        "range": v.get("range"),
        "direct_advisories": [(a["url"], a["title"], a.get("range"), a.get("severity")) for a in direct_advisories],
        "sub_pkgs": sub_pkgs,
        "fixAvailable": v.get("fixAvailable"),
    }

for group,name in [("PROD",p) for p in prod] + [("DEV",p) for p in dev]:
    s = summarize(name)
    if s:
        print(f"=== [{group}] {name} severity={s['severity']} range={s['range']} fix={s['fixAvailable']}")
        for u,t,r,sev in s['direct_advisories']:
            print(f"    ADVISORY: {t} | {u} | range={r} | sev={sev}")
        if s['sub_pkgs']:
            print(f"    transitive-via: {s['sub_pkgs']}")
EOF","description":"Summarize each declared dependency's audit findings"}

