    if name in seen or name not in vulns: return
    seen.add(name)
    v = vulns[name]
    print("  "*depth + f"{name} sev={v.get('severity')} range={v.get('range')}")
    for x in v["via"]:
        if isinstance(x, dict):
            print("  "*(depth+1) + f"ADV: {x['title']} sev={x.get('severity')} {x['url']} range={x.get('range')}")
